function validate([mat, target]) {
  const n = Array.isArray(mat) ? mat.length : 0;
  if (n < 1 || n > 10) return 'mat needs 1 to 10 rows.';
  if (!Array.isArray(target) || target.length !== n) return 'target must have the same size as mat.';
  for (const grid of [mat, target]) {
    for (const row of grid) {
      if (!Array.isArray(row) || row.length !== n) return 'Both grids must be n x n.';
      if (row.some(v => v !== 0 && v !== 1)) return 'Every cell is 0 or 1.';
    }
  }
  return null;
}

