function findRotation(mat, target) {
  const n = mat.length;
  const fits = [true, true, true, true];

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const value = target[i][j];
      if (mat[i][j] !== value) fits[0] = false;
      if (mat[n - 1 - j][i] !== value) fits[1] = false;
      if (mat[n - 1 - i][n - 1 - j] !== value) fits[2] = false;
      if (mat[j][n - 1 - i] !== value) fits[3] = false;
    }
  }
  return fits.includes(true);
}

