function generate(rand, size) {
  const n = size === 'large' ? 7 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 4);
  const density = rand();
  const mat = Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  let target;
  const mode = Math.floor(rand() * 4);
  if (mode === 0) {
    target = Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  } else {
    // Turn mat a random number of times, and sometimes flip one cell or mirror it.
    target = mat.map(row => row.slice());
    const turns = Math.floor(rand() * 4);
    for (let t = 0; t < turns; t++) target = target[0].map((_, c) => target.map(row => row[c]).reverse());
    if (mode === 2) { const r = Math.floor(rand() * n), c = Math.floor(rand() * n); target[r][c] ^= 1; }
    if (mode === 3 && rand() < 0.5) target = target.map(row => row.slice().reverse());
  }
  return [mat, target];
}
